import { Separator as BaseSeparator } from "@base-ui/react/separator";
import type { ComponentPropsWithoutRef, ElementType } from "react";
import { cn } from "../../lib/cn";
import "../../styles/separator.css";

type StaticClass<T extends ElementType> = Omit<ComponentPropsWithoutRef<T>, "className"> & {
  className?: string;
};

/** Hairline divider. Decorative by default, so it is not announced to screen readers. */
export function Separator({ className, ...props }: StaticClass<typeof BaseSeparator>) {
  return <BaseSeparator className={cn("eui-separator", className)} {...props} />;
}

/**
 * Joins class names, skipping falsy values.
 * Kept tiny on purpose: components own their class lists, so no merge step is needed.
 */
export function cn(...inputs: Array<string | false | null | undefined>): string {
  return inputs.filter(Boolean).join(" ");
}

/* Separator. A 1px hairline in the border token. */

.eui-separator {
  flex: none;
  margin: 0;
  border: 0;
  background-color: var(--eui-color-border);
  height: var(--eui-border-width);
  width: 100%;
}

.eui-separator[aria-orientation="vertical"] {
  width: var(--eui-border-width);
  height: auto;
  align-self: stretch;
}
